INSERT INTO artisans (id, name, bio, specialty, location, image, experience, rating) VALUES
(1,  'Rajesh Kumar',       'Preserving 3rd-generation blue pottery traditions with sustainable natural glazes and custom monogram engravings.', 'Master Potter & Ceramicist',      'Jaipur, Rajasthan',          'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=300&q=80', '18+ years', 4.9),
(2,  'Meenakshi Sundaram', 'Weaving hand-spun organic cotton and natural vegetable dye tapestries using authentic wooden pit looms.',          'Handloom & Textile Weaver',       'Madurai, Tamil Nadu',         'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=300&q=80', '12+ years', 4.8),
(3,  'Arjun Somvanshi',    'Hand-carving reclaimed rosewood and teak into timeless keepsake boxes and architectural accents.',                  'Rosewood & Brass Craftsman',      'Saharanpur, Uttar Pradesh',   'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=300&q=80', '15+ years', 5.0),
(4,  'Ananya Bose',        'Blending Madhubani and Warli folk art with contemporary resin art — each piece is an original creation.',          'Folk Painter & Resin Artist',     'Kolkata, West Bengal',        'https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=300&q=80', '8+ years',  4.9),
(5,  'Kavitha Swaminathan', 'Creating contemporary handcrafted jewellery blending tribal traditions with modern aesthetics using recycled metals.', 'Jewellery & Metalwork Artist',  'Chennai, Tamil Nadu',         'https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=300&q=80', '10+ years', 4.8),
(6,  'Balram Patra',       'A 4th-generation Channapatna craftsman preserving the art of turning eco-toys using natural lacquer.',             'Channapatna Lacquerwood Artist',  'Channapatna, Karnataka',      'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?auto=format&fit=crop&w=300&q=80', '20+ years', 4.9),
(7,  'Fatima Sheikh',      'Creating heritage Zardozi embroidery using metallic gold and silver threads on velvet and silk fabrics.',          'Zardozi Thread Embroiderer',      'Lucknow, Uttar Pradesh',      'https://images.unsplash.com/photo-1567532939604-b6b5b0db2604?auto=format&fit=crop&w=300&q=80', '11+ years', 4.9),
(8,  'Sunita Devi',        'National award-winning Mithila artist painting stories of folklore and nature onto handmade cotton parchment.',    'Madhubani Master Painter',        'Madhubani, Bihar',            'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=300&q=80', '20+ years', 5.0),
(9,  'Lalita Rathore',     'Practicing traditional Dabu mud-resist and Bagru block printing with natural indigo vats.',                        'Block Print Artisan',             'Bagru, Rajasthan',            'https://images.unsplash.com/photo-1573497019940-1c28c88b4f3e?auto=format&fit=crop&w=300&q=80', '13+ years', 4.8),
(10, 'Tenzing Norbu',      'Hand-knotting pure sheep wool rugs and Himalayan meditation prayer accessories for 17 years.',                     'Himalayan Wool Weaver',           'Dharamshala, Himachal Pradesh','https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?auto=format&fit=crop&w=300&q=80', '17+ years', 4.9);
